/**
 * @title PWN Deployer
 * @notice Contract that deploys other PWN protocol contracst with `CREATE2` opcode, to have same addresses on different chains.
 */
contract PWNDeployer is Ownable {

    string internal constant VERSION = "1.0";

    /*----------------------------------------------------------*|
    |*  # CONSTRUCTOR                                           *|
    |*----------------------------------------------------------*/

    constructor() Ownable() {

    }


    /*----------------------------------------------------------*|
